/**
 * @fileoverview Cloudflare Workers entry point
 *
 * This file integrates the Hono API with Astro SSR.
 */


import { app as honoApp } from "./backend/api/index";
// @ts-ignore - this file is generated by Astro after build
import astroHandler from "../dist/_worker.js/index.js";

// Export Durable Object agents for Cloudflare Workers runtime
export { RenovationAgent } from "./backend/ai/agents/RenovationAgent";

const handler: ExportedHandler<Env> = {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // Handle API routes with Hono
    if (
      url.pathname.startsWith("/api/") ||
      url.pathname === "/openapi.json" ||
      url.pathname === "/swagger" ||
      url.pathname === "/scalar" ||
      url.pathname === "/docs" ||
      url.pathname === "/context"
    ) {
      return honoApp.fetch(request, env, ctx);
    }

    // Let Astro handle everything else (SSR and static assets via env.ASSETS)
    return astroHandler.fetch!(request, env, ctx);
  },
};

export default handler;
